/* Signature Latvian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Janisberz": "From Janis + berzs (birch).", "Annakalns": "From Anna + kalns (hill).", "Peterisozols": "From Peteris + ozols (oak).", "Ilzeliepa": "From Ilze + liepa (linden).", "Andrisjura": "From Andris + jura (sea).", "Ligasaul": "From Liga + saule (sun).", "Janisberzins": "Signature surname in -ins style; feminine Janisberzina.", "Annakalnins": "Signature surname; feminine Annakalnina.", "Peterisozolins": "Signature surname; feminine Peterisozolina.", "Ligasaulins": "Signature surname; feminine Ligasaulina."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Janisberz';
console.log(lookup(q));

